/* ChatGPT Desktop — interactive frontend replica.
 * Structure + class names are taken from the real Electron renderer (see ../spec).
 * Data comes from the local Codex thread store (see ../tools/export_data.py).
 */
'use strict';

/* ------------------------------------------------------------------ utils */
const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));

const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const pad = (n) => String(n).padStart(2, '0');

function fmtClock(sec) {
  if (!sec) return '';
  const d = new Date(sec * 1000);
  return `${d.getHours()}:${pad(d.getMinutes())}`;
}

function fmtDay(sec) {
  if (!sec) return '';
  const d = new Date(sec * 1000);
  const today = new Date();
  const same = d.toDateString() === today.toDateString();
  if (same) return '今天';
  return `${d.getMonth() + 1}月${d.getDate()}日`;
}

function fmtDuration(ms) {
  if (!ms || ms < 0) return '';
  const s = Math.round(ms / 1000);
  if (s < 60) return `${s}秒`;
  const m = Math.floor(s / 60);
  const rest = s % 60;
  if (m < 60) return rest ? `${m}分钟 ${rest}秒` : `${m}分钟`;
  const h = Math.floor(m / 60);
  return `${h}小时 ${m % 60}分钟`;
}

function relTime(sec) {
  if (!sec) return '';
  const diff = Date.now() / 1000 - sec;
  if (diff < 60) return '刚刚';
  if (diff < 3600) return `${Math.floor(diff / 60)} 分钟前`;
  if (diff < 86400) return `${Math.floor(diff / 3600)} 小时前`;
  if (diff < 86400 * 7) return `${Math.floor(diff / 86400)} 天前`;
  return fmtDay(sec);
}

function shortPath(p) {
  if (!p) return '';
  return String(p).replace(/^\\\\\?\\/, '').replace(/^[A-Za-z]:\\Users\\[^\\]+\\/, '~\\');
}

const ICON = {
  chevron: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M9 6l6 6-6 6" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  check: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M4.5 12.5l5 5 10-11" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  copy: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true"><rect x="9" y="9" width="11" height="11" rx="2.5" stroke="currentColor" stroke-width="1.6"/><path d="M15 5.5A2.5 2.5 0 0012.5 3H6.5A2.5 2.5 0 004 5.5v6A2.5 2.5 0 006.5 14" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>',
  terminal: '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true"><rect x="3" y="4.5" width="18" height="15" rx="3" stroke="currentColor" stroke-width="1.6"/><path d="M7 10l2.5 2L7 14M12.5 14.5H16" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  file: '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M13 3.5H7.5A2.5 2.5 0 005 6v12a2.5 2.5 0 002.5 2.5h9A2.5 2.5 0 0019 18V9.5L13 3.5z" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/><path d="M13 3.8V9.5h5.6" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/></svg>',
  agent: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="12" cy="8" r="3.4" stroke="currentColor" stroke-width="1.6"/><path d="M4.8 20c.6-3.6 3.6-5.6 7.2-5.6s6.6 2 7.2 5.6" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>',
  branch: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="7" cy="6" r="2.4" stroke="currentColor" stroke-width="1.6"/><circle cx="7" cy="18" r="2.4" stroke="currentColor" stroke-width="1.6"/><circle cx="17" cy="9" r="2.4" stroke="currentColor" stroke-width="1.6"/><path d="M7 8.4v7.2M9.4 18h3.2a2.4 2.4 0 002.4-2.4V11.4" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>',
  search: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="11" cy="11" r="6.2" stroke="currentColor" stroke-width="1.7"/><path d="M15.6 15.6L20 20" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg>',
  arrowDown: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 5v14M6 13l6 6 6-6" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  dot: '<span class="inline-block size-1.5 rounded-full bg-current"></span>',
};

/* ------------------------------------------------------- markdown (small) */
function renderMarkdown(src) {
  if (!src) return '';
  const blocks = [];
  let text = String(src).replace(/\r\n/g, '\n');

  // fenced code
  text = text.replace(/```([\w+-]*)\n([\s\S]*?)```/g, (_, lang, code) => {
    const idx = blocks.length;
    blocks.push(`<pre class="overflow-x-auto rounded-lg bg-surface-secondary p-3 text-xs leading-relaxed"><code>${esc(code.replace(/\n$/, ''))}</code></pre>`);
    return `\u0000CODE${idx}\u0000`;
  });

  const inline = (s) => esc(s)
    .replace(/`([^`\n]+)`/g, '<code class="rounded bg-surface-secondary px-1 py-0.5 text-[0.92em]">$1</code>')
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/(^|[\s(])\*([^*\n]+)\*/g, '$1<em>$2</em>')
    .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '<a href="$2" target="_blank" rel="noreferrer" class="underline decoration-1 underline-offset-2">$1</a>');

  const lines = text.split('\n');
  const out = [];
  let list = null;
  let para = [];
  let codeBlock = null;

  const flushPara = () => {
    if (para.length) { out.push(`<p class="Paragraph-kKnbIo">${inline(para.join(' '))}</p>`); para = []; }
  };
  const flushList = () => {
    if (list) { out.push(`<${list.tag} class="ps-6 my-2 list-${list.tag === 'ol' ? 'decimal' : 'disc'}">${list.items.map(i => `<li>${inline(i)}</li>`).join('')}</${list.tag}>`); list = null; }
  };

  for (const raw of lines) {
    const line = raw;
    const codeMatch = line.match(/^\u0000CODE(\d+)\u0000$/);
    if (codeMatch) { flushPara(); flushList(); out.push(blocks[Number(codeMatch[1])]); continue; }
    if (!line.trim()) { flushPara(); flushList(); continue; }
    const h = line.match(/^(#{1,4})\s+(.*)$/);
    if (h) { flushPara(); flushList(); const lv = h[1].length; out.push(`<h${lv} class="mt-4 mb-1.5 font-semibold">${inline(h[2])}</h${lv}>`); continue; }
    if (/^>\s?/.test(line)) { flushPara(); flushList(); out.push(`<blockquote class="border-s-2 border-subtle ps-3 my-2 text-secondary">${inline(line.replace(/^>\s?/, ''))}</blockquote>`); continue; }
    if (/^\s*[-*+]\s+/.test(line)) { flushPara(); if (!list || list.tag !== 'ul') { flushList(); list = { tag: 'ul', items: [] }; } list.items.push(line.replace(/^\s*[-*+]\s+/, '')); continue; }
    if (/^\s*\d+[.)]\s+/.test(line)) { flushPara(); if (!list || list.tag !== 'ol') { flushList(); list = { tag: 'ol', items: [] }; } list.items.push(line.replace(/^\s*\d+[.)]\s+/, '')); continue; }
    if (/^(-{3,}|\*{3,})$/.test(line.trim())) { flushPara(); flushList(); out.push('<hr class="my-4 border-subtle" />'); continue; }
    para.push(line.trim());
  }
  flushPara(); flushList();
  return out.join('');
}

/* --------------------------------------------------------------- app state */
const state = {
  threads: [],
  projects: [],
  agents: [],
  current: null,       // thread document
  currentId: null,
  view: 'home',
  turnsShown: 30,
  theme: 'light',
  sent: [],            // locally composed messages (demo)
};

const THREADS_BY_ID = new Map();

/* ------------------------------------------------------------ bootstrapping */
async function boot() {
  const [threads, projects, agents] = await Promise.all([
    fetch('/data/threads.json').then(r => r.json()),
    fetch('/data/projects.json').then(r => r.json()),
    fetch('/data/agents.json').then(r => r.json()),
  ]);
  state.threads = threads;
  state.projects = projects;
  state.agents = agents;
  threads.forEach(t => THREADS_BY_ID.set(t.id, t));

  // agent thread id -> friendly name (from the spawn path)
  for (const a of agents) {
    if (!a.agentThreadId) continue;
    const name = a.agentPath ? a.agentPath.split('/').filter(Boolean).pop() : null;
    if (name) AGENT_NAME_BY_THREAD.set(a.agentThreadId, name);
  }

  await injectPartials();
  buildSidebar();
  wireTopbar();
  wireSidebarNav();
  wireProfileMenu();
  wireHomeComposer();
  wireGlobalKeys();
  buildSearchDialog();

  window.addEventListener('hashchange', route);
  route();
}

async function injectPartials() {
  const [topbar, aside, composer] = await Promise.all([
    fetch('/partials/topbar.html').then(r => r.text()),
    fetch('/partials/aside.html').then(r => r.text()),
    fetch('/partials/composer.html').then(r => r.text()),
  ]);
  $('#topbar-slot').innerHTML = topbar;
  $('#sidebar-slot').innerHTML = aside;
  $('#home-view').innerHTML = composer;
}

/* ------------------------------------------------------------------ sidebar */
function threadTitle(t) {
  const s = (t.title || '').replace(/\s+/g, ' ').trim();
  if (s && s !== '(无标题)') {
    if (s.startsWith('# Files pasted') || s.startsWith('# Files mentioned')) {
      const m = s.match(/#\s*"([^"]{6,80})"/);
      return m ? m[1] : '粘贴文件的会话';
    }
    return s.length > 64 ? s.slice(0, 62) + '…' : s;
  }
  // subagent threads have no title: derive it from the spawn path
  const agentName = AGENT_NAME_BY_THREAD.get(t.id);
  if (agentName) return agentName;
  return '未命名会话';
}

const AGENT_NAME_BY_THREAD = new Map();

function projectOf(t) {
  if (!t.cwd) return null;
  const cwd = shortPath(t.cwd).toLowerCase();
  let best = null;
  for (const p of state.projects) {
    for (const root of p.roots || []) {
      const r = shortPath(root).toLowerCase().replace(/\\+$/, '');
      if (r && cwd.startsWith(r)) {
        if (!best || r.length > best.len) best = { name: p.name, len: r.length };
      }
    }
  }
  return best ? best.name : null;
}

function buildSidebar() {
  const aside = $('aside');
  if (!aside) return;

  const firstRow = $('[data-app-action-sidebar-thread-row]', aside);
  if (!firstRow) return;

  // the scrollable list that holds the sections
  let host = firstRow.parentElement;
  while (host && host !== aside) {
    const cs = getComputedStyle(host);
    if (cs.overflowY === 'auto' || cs.overflowY === 'scroll') break;
    host = host.parentElement;
  }
  if (!host || host === aside) host = firstRow.parentElement;

  const rowTpl = firstRow.outerHTML;
  const sectionTitleTpl = (() => {
    const t = $('[class*="nav-section-title"]', aside);
    return t ? t.outerHTML : null;
  })();
  const newChatBtn = $$('button', aside).find(b => (b.innerText || '').trim() === '新聊天');
  const newChatWasInHost = newChatBtn ? host.contains(newChatBtn) : false;

  host.innerHTML = '';
  host.classList.add('flex', 'flex-col', 'gap-px');

  // 新聊天 — only re-create it if we just wiped the original
  if (newChatBtn && newChatWasInHost) {
    const wrap = document.createElement('div');
    wrap.className = 'flex shrink-0 items-center browser:w-full';
    wrap.appendChild(newChatBtn.cloneNode(true));
    host.appendChild(wrap);
    wrap.addEventListener('click', () => { location.hash = ''; });
  }

  const makeTitle = (label, extra) => {
    const d = document.createElement('div');
    d.className = 'group/nav-section-title flex min-h-[var(--height-token-row)] items-center justify-between gap-2 ps-2 pe-1.5 pt-2 pb-1 select-none';
    d.innerHTML = `<div class="min-w-0 flex-1 text-base font-medium text-tertiary">${esc(label)}</div>` +
      (extra ? `<div class="flex items-center gap-0.5">${extra}</div>` : '');
    return d;
  };

  const makeRow = (t, opts = {}) => {
    const tmp = document.createElement('div');
    tmp.innerHTML = rowTpl;
    const row = tmp.firstElementChild;
    row.setAttribute('data-app-action-sidebar-thread-id', 'local:' + t.id);
    row.setAttribute('data-app-action-sidebar-thread-title', threadTitle(t));
    row.setAttribute('aria-label', threadTitle(t));
    row.setAttribute('data-thread-id', t.id);
    const titleSpan = $('[data-thread-title]', row);
    if (titleSpan) titleSpan.textContent = threadTitle(t);
    // remove the hover rail of buttons to keep it clean but keep the slot
    if (opts.indent) {
      row.classList.add('ps-6');
      const lead = row.firstElementChild?.firstElementChild;
      if (lead) lead.innerHTML = `<span class="flex w-4 shrink-0 items-center justify-center text-tertiary">${ICON.branch}</span>`;
    }
    if (opts.agent) {
      row.setAttribute('data-agent-row', '1');
      row.classList.add('text-secondary');
    }
    return row;
  };

  // 最近
  host.appendChild(makeTitle('最近', `<button class="Button-BZrLNX" data-color="secondary" data-variant="ghost" data-size="xs" title="搜索">${ICON.search}</button>`));

  const recent = [...state.threads].sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0));
  const unprojected = recent.filter(t => !projectOf(t));
  const shown = unprojected.slice(0, 40);

  for (const t of shown) {
    const row = makeRow(t);
    row.addEventListener('click', () => { location.hash = '#/t/' + t.id; });
    host.appendChild(row);
  }
  if (unprojected.length > shown.length) {
    const more = document.createElement('button');
    more.className = 'text-sm text-tertiary hover:text-default px-2 py-1 text-start';
    more.textContent = `显示更多（还有 ${unprojected.length - shown.length} 条）`;
    more.addEventListener('click', () => {
      for (const t of unprojected.slice(shown.length)) {
        const row = makeRow(t);
        row.addEventListener('click', () => { location.hash = '#/t/' + t.id; });
        host.insertBefore(row, more);
      }
      more.remove();
    });
    host.appendChild(more);
  }

  // 项目
  const byProject = new Map();
  for (const t of recent) {
    const p = projectOf(t);
    if (!p) continue;
    if (!byProject.has(p)) byProject.set(p, []);
    byProject.get(p).push(t);
  }
  if (byProject.size) {
    host.appendChild(makeTitle('项目'));
    for (const [name, list] of [...byProject.entries()].sort((a, b) => b[1].length - a[1].length)) {
      const groupWrap = document.createElement('div');
      groupWrap.className = 'contents';

      const head = document.createElement('div');
      head.setAttribute('role', 'button');
      head.tabIndex = 0;
      head.className = 'group relative cursor-interaction text-sm hover:bg-secondary-ghost-hover h-[var(--height-token-row)] sidebar-item flex items-center gap-2 px-2 rounded-md';
      head.innerHTML = `<span class="flex w-4 shrink-0 items-center justify-center text-tertiary transition-transform">${ICON.chevron}</span>
        <span class="min-w-0 flex-1 truncate text-default">${esc(name)}</span>
        <span class="text-xs text-tertiary">${list.length}</span>`;
      groupWrap.appendChild(head);

      const body = document.createElement('div');
      body.className = 'hidden flex-col';
      for (const t of list.slice(0, 30)) {
        const row = makeRow(t);
        row.addEventListener('click', () => { location.hash = '#/t/' + t.id; });
        body.appendChild(row);
      }
      groupWrap.appendChild(body);

      head.addEventListener('click', () => {
        const open = body.classList.toggle('hidden');
        $('span', head).style.transform = open ? '' : 'rotate(90deg)';
      });

      host.appendChild(groupWrap);
    }
  }

  // 子代理区（当前会话有子代理时）— 放在「最近」之后、「项目」之前
  renderAgentSection(host, makeTitle, makeRow);
}

function agentSectionAnchor(host) {
  // the 项目 section title, if present
  for (const el of $$('[class*="nav-section-title"]', host)) {
    if ((el.textContent || '').trim().startsWith('项目')) return el;
  }
  return null;
}

function renderAgentSection(host, makeTitle, makeRow) {
  const old = $('#agent-section', host);
  if (old) old.remove();
  if (!state.current) return;

  const agents = collectAgents(state.current);
  if (!agents.length) return;

  const wrap = document.createElement('div');
  wrap.id = 'agent-section';
  wrap.className = 'flex flex-col gap-px';
  wrap.appendChild(makeTitle(`子代理 · ${agents.length}`));

  for (const a of agents) {
    const row = document.createElement('div');
    row.setAttribute('role', 'button');
    row.tabIndex = 0;
    row.setAttribute('data-agent-row', '1');
    row.className = 'group relative cursor-interaction text-sm hover:bg-secondary-ghost-hover h-[var(--height-token-row)] sidebar-item flex items-center gap-2 ps-4 pe-2 rounded-md';
    const statusColor = a.kind === 'completed' ? 'text-green-500'
      : a.kind === 'started' ? 'text-blue-400'
        : a.kind === 'interrupted' ? 'text-red-400' : 'text-tertiary';
    row.innerHTML = `
      <span class="flex w-4 shrink-0 items-center justify-center ${statusColor}">${ICON.agent}</span>
      <span class="min-w-0 flex-1 truncate" title="${esc(a.path)}">${esc(a.name)}</span>
      <span class="text-[11px] text-tertiary">${esc(a.kind)}</span>`;
    if (THREADS_BY_ID.has(a.threadId)) {
      row.addEventListener('click', () => { location.hash = '#/t/' + a.threadId; });
    } else {
      row.classList.add('opacity-60');
      row.title = '该子代理会话没有本地记录';
    }
    wrap.appendChild(row);
  }
  const anchor = agentSectionAnchor(host);
  if (anchor) host.insertBefore(wrap, anchor);
  else host.appendChild(wrap);
}

function collectAgents(doc) {
  const map = new Map();
  for (const turn of doc.turns || []) {
    for (const it of turn.items || []) {
      if (it.type !== 'subAgentActivity' || !it.agentThreadId) continue;
      const prev = map.get(it.agentThreadId) || {};
      const path = it.agentPath || prev.path || '';
      map.set(it.agentThreadId, {
        threadId: it.agentThreadId,
        path,
        name: path ? path.split('/').filter(Boolean).pop() : (it.agentThreadId || '').slice(0, 8),
        kind: it.kind || prev.kind || '',
      });
    }
  }
  return [...map.values()];
}

/* ============================================================================
 * Settings page — layout copied from the live ChatGPT settings route:
 *   nav column 288px (padding 4/8/8, gap 16), item 262×30, radius 12.5,
 *   font 13/400, selected bg rgba(13,13,13,.055)
 *   content: h1 28/500/33.6, row padding 12px 16px, gap 24,
 *   label 13/500, description 12/16 secondary, control on the right
 * ==========================================================================*/

const SETTINGS_NAV = [
  {
    group: '个人',
