}

/* ------------------------------------------------------------------ routing */
function route() {
  const m = location.hash.match(/^#\/t\/(.+)$/);
  if (m) { openThread(decodeURIComponent(m[1])); return; }
  if (/^#\/settings(\/([\w-]+))?$/.test(location.hash)) {
    openSettings(location.hash.split('/')[2] || null);
    return;
  }
  showHome();
}

