/* Minimal glue so the real stylesheet drives a static, data-bound app. */

html, body {
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: var(--color-background-primary, #fff);
  color: var(--color-text, #0d0d0d);
  font-family: var(--font-sans, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif);
}

#root { height: 100%; }
#shell { height: 100%; }

/* the app's PageSurface normally comes from its own layout component */
#page-surface {
  min-width: 0;
  position: relative;
}

/* home view: the extracted home layout is height-driven; give it room */
