  let text = String(src).replace(/\r\n/g, '\n');

  // fenced code
  text = text.replace(/```([\w+-]*)\n([\s\S]*?)```/g, (_, lang, code) => {
    const idx = blocks.length;
    blocks.push(`<pre class="overflow-x-auto rounded-lg bg-surface-secondary p-3 text-xs leading-relaxed"><code>${esc(code.replace(/\n$/, ''))}</code></pre>`);
    return `\u0000CODE${idx}\u0000`;
  });

  const inline = (s) => esc(s)
    .replace(/`([^`\n]+)`/g, '<code class="rounded bg-surface-secondary px-1 py-0.5 text-[0.92em]">$1</code>')
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/(^|[\s(])\*([^*\n]+)\*/g, '$1<em>$2</em>')
    .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '<a href="$2" target="_blank" rel="noreferrer" class="underline decoration-1 underline-offset-2">$1</a>');

  const lines = text.split('\n');
  const out = [];
  let list = null;
  let para = [];
  let codeBlock = null;

  const flushPara = () => {
    if (para.length) { out.push(`<p class="Paragraph-kKnbIo">${inline(para.join(' '))}</p>`); para = []; }
  };
  const flushList = () => {
    if (list) { out.push(`<${list.tag} class="ps-6 my-2 list-${list.tag === 'ol' ? 'decimal' : 'disc'}">${list.items.map(i => `<li>${inline(i)}</li>`).join('')}</${list.tag}>`); list = null; }
  };

  for (const raw of lines) {
    const line = raw;
    const codeMatch = line.match(/^\u0000CODE(\d+)\u0000$/);
    if (codeMatch) { flushPara(); flushList(); out.push(blocks[Number(codeMatch[1])]); continue; }
    if (!line.trim()) { flushPara(); flushList(); continue; }
    const h = line.match(/^(#{1,4})\s+(.*)$/);
    if (h) { flushPara(); flushList(); const lv = h[1].length; out.push(`<h${lv} class="mt-4 mb-1.5 font-semibold">${inline(h[2])}</h${lv}>`); continue; }
    if (/^>\s?/.test(line)) { flushPara(); flushList(); out.push(`<blockquote class="border-s-2 border-subtle ps-3 my-2 text-secondary">${inline(line.replace(/^>\s?/, ''))}</blockquote>`); continue; }
    if (/^\s*[-*+]\s+/.test(line)) { flushPara(); if (!list || list.tag !== 'ul') { flushList(); list = { tag: 'ul', items: [] }; } list.items.push(line.replace(/^\s*[-*+]\s+/, '')); continue; }
    if (/^\s*\d+[.)]\s+/.test(line)) { flushPara(); if (!list || list.tag !== 'ol') { flushList(); list = { tag: 'ol', items: [] }; } list.items.push(line.replace(/^\s*\d+[.)]\s+/, '')); continue; }
    if (/^(-{3,}|\*{3,})$/.test(line.trim())) { flushPara(); flushList(); out.push('<hr class="my-4 border-subtle" />'); continue; }
    para.push(line.trim());
  }
  flushPara(); flushList();
  return out.join('');
}

