function workerIdentity(event: TimelineEvent, runs: WorkerRun[]): string {
  const run = event.run_id ? runs.find((item) => item.run_id === event.run_id) : undefined;
  if (!event.worker_id && !run) return "";
  return ["Worker", run?.role, event.worker_id, event.run_id, run?.provider_id, run?.model_id].filter(Boolean).join(" · ");
}

function CommandCard({ detail, onInspect }: { detail: Row; onInspect: () => void }) {
  const [copyStatus, setCopyStatus] = useState("");
  const command = text(detail.command, "");
  // The current Core normally returns a receipt digest, not stdout. Never infer output from it.
  const output = [detail.stdout, detail.output, detail.stderr].filter((value): value is string => typeof value === "string").join("\n");
  const copy = async () => {
    onInspect();
    try { await navigator.clipboard.writeText(command); setCopyStatus("已复制"); }
    catch { setCopyStatus("无法复制，请手动选择代码。"); }
  };
  return <div className="command-card"><header>{toolLabel(detail.tool, "命令")}</header>
    <div className="command-line"><div className="cmd">{command}</div><button type="button" className="copy-btn" aria-label="复制" onClick={() => void copy()}><svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.3" aria-hidden="true"><rect x="5.5" y="5.5" width="8" height="8" rx="1.5" /><path d="M10.5 5.5v-2a1 1 0 0 0-1-1h-6a1 1 0 0 0-1 1v6a1 1 0 0 0 1 1h2" /></svg></button></div>
    {output ? <div className="out vertical-scroll-fade-mask"><code>{output}</code></div> : <p className="command-no-output">暂无输出</p>}
