function EventGroup({ item, quests, runs, memory, onQuest, onInspect }: { item: Extract<DisplayItem, { type: "group" }>; quests: Quest[]; runs: WorkerRun[]; memory: EventViewMemory; onQuest: (id: string) => void; onInspect: () => void }) {
  const [expanded, setExpanded] = useState(() => item.events.some((event) => eventView(memory, event).groupExpanded));
  // Members inherit the current group state, so splits and prepended group roots restore it.
  useLayoutEffect(() => {
    for (const event of item.events) eventView(memory, event).groupExpanded = expanded;
  }, [item.events, memory, expanded]);
  const summary = [...new Set(item.events.map(eventTitle))].join("");
  const origins = [...new Set(item.events.map((event) => workerIdentity(event, runs)).filter(Boolean))];
  return <AnimatedDetails className="event-group" scrollKey={`group:${eventKey(item.events[0])}`} initialExpanded={expanded} onExpandedChange={(value) => { for (const event of item.events) eventView(memory, event).groupExpanded = value; setExpanded(value); }} onInspect={onInspect} summaryTitle={origins.join("\n")} summaryLabel={item.events.length > 2 ? `查看较早的 ${item.events.length - 2} 条${item.questId ? "任务记录" : "后台活动"}` : undefined} summary={<><ActivityIcon event={item.events[0]} /><span className="event-label">{summary}</span><Chevron /></>}>
