function EventLine({ event, quests, runs, memory, groupExpanded, onQuest, onInspect }: { event: TimelineEvent; quests: Quest[]; runs: WorkerRun[]; memory: EventViewMemory; groupExpanded: boolean; onQuest: (id: string) => void; onInspect: () => void }) {
  const view = eventView(memory, event), key = eventKey(event);
  const [expanded, setExpanded] = useState(view.expanded || false);
  const detail = event.detail && typeof event.detail === "object" && !Array.isArray(event.detail) ? event.detail as Row : {};
  const relatedQuest = quests.find((quest) => quest.id === event.quest_id);
  const target = typeof detail.path === "string" ? detail.path : typeof detail.command === "string" ? detail.command : "";
  const failed = event.status === "failed" || event.status === "worker.failed" || event.status === "tool.execution_uncertain" || (typeof detail.exit_code === "number" && detail.exit_code !== 0);
  const unknown = event.status === "unknown" || event.status === "uncertain" || event.status === "tool.execution_uncertain";
  const record = <>
    {workerIdentity(event, runs) && <p className="event-origin" title={workerIdentity(event, runs)}>{workerIdentity(event, runs)}</p>}
    <p>{event.execution_mode === "live" ? "真实执行" : event.execution_mode === "mock" ? "模拟" : "来源未知"} · {event.created_at ? new Date(event.created_at).toLocaleString() : "时间未知"}</p>
    {event.quest_id && <button className="text-button" aria-label="查看关联任务" onClick={() => onQuest(event.quest_id!)}>查看关联任务{relatedQuest ? ` · ${relatedQuest.title}` : ""}</button>}
    <dl>{Object.entries(detail).filter(([key]) => !(typeof detail.command === "string" && ["stdout", "output", "stderr"].includes(key))).map(([key, value]) => <div key={key}><dt>{({ path: "路径", tool: "工具", result_sha256: "结果摘要", command: "命令", exit_code: "退出码", scope: "范围", source_count: "来源数", status: "状态", risk: "风险" } as Record<string, string>)[key] || key}</dt><dd>{key === "tool" ? toolLabel(value) : key === "status" ? statusLabel(value) : key === "risk" ? riskLabel(value) : text(value)}</dd></div>)}</dl>
    <small>记录 ID：{event.event_id}</small>
  </>;
  return <AnimatedDetails onInspect={onInspect} scrollKey={`event:${key}`} initialExpanded={expanded} onExpandedChange={(value) => { view.expanded = value; setExpanded(value); }} className={`event-line${failed ? " failed" : ""}${unknown ? " unknown" : ""}`} summaryTitle={[workerIdentity(event, runs), target].filter(Boolean).join("\n")} summary={<><ActivityIcon event={event} /><span className="event-label">{target || eventTitle(event)}{(failed || unknown) && <span className="event-failed"> · {unknown ? "结果未知" : "失败"}{typeof detail.exit_code === "number" ? `（退出码 ${detail.exit_code}）` : ""}</span>}{event.execution_mode === "mock" && <small className="event-mode"> · 模拟</small>}</span><Chevron /></>}>
    <div className="event-detail">
      {typeof detail.command === "string" && <CommandCard detail={detail} visible={groupExpanded && expanded} savedScrollTop={memory.commandScroll.get(key) || 0} onScroll={(scrollTop) => memory.commandScroll.set(key, scrollTop)} onInspect={onInspect} />}
      {["file_write", "file_revise"].includes(text(detail.tool, "")) && typeof detail.path === "string" && <div className="resource-card"><span className="resource-icon" aria-hidden="true"><ActivityIcon event={event} /></span><span><strong>{detail.path}</strong><small>{eventTitle(event)}</small></span></div>}
      {typeof detail.command === "string"
        ? <AnimatedDetails className="event-record" initialExpanded={view.recordExpanded || false} onExpandedChange={(value) => { view.recordExpanded = value; }} onInspect={onInspect} summary={<><span>记录详情</span><Chevron /></>}><div className="event-record-content">{record}</div></AnimatedDetails>
        : record}
    </div></AnimatedDetails>;
}

function EventGroup({ item, quests, runs, memory, onQuest, onInspect }: { item: Extract<DisplayItem, { type: "group" }>; quests: Quest[]; runs: WorkerRun[]; memory: EventViewMemory; onQuest: (id: string) => void; onInspect: () => void }) {
  const [expanded, setExpanded] = useState(() => item.events.some((event) => eventView(memory, event).groupExpanded));
  // Members inherit the current group state, so splits and prepended group roots restore it.
  useLayoutEffect(() => {
    for (const event of item.events) eventView(memory, event).groupExpanded = expanded;
  }, [item.events, memory, expanded]);
  const summary = [...new Set(item.events.map(eventTitle))].join("");
  const origins = [...new Set(item.events.map((event) => workerIdentity(event, runs)).filter(Boolean))];
  return <AnimatedDetails className="event-group" scrollKey={`group:${eventKey(item.events[0])}`} initialExpanded={expanded} onExpandedChange={(value) => { for (const event of item.events) eventView(memory, event).groupExpanded = value; setExpanded(value); }} onInspect={onInspect} summaryTitle={origins.join("\n")} summaryLabel={item.events.length > 2 ? `查看较早的 ${item.events.length - 2} 条${item.questId ? "任务记录" : "后台活动"}` : undefined} summary={<><ActivityIcon event={item.events[0]} /><span className="event-label">{summary}</span><Chevron /></>}>
    <div className="event-detail">{item.events.map((event) => <EventLine key={eventKey(event)} event={event} quests={quests} runs={runs} memory={memory} groupExpanded={expanded} onQuest={onQuest} onInspect={onInspect} />)}</div>
  </AnimatedDetails>;
}
function groupEvents(items: TimelineItem[]): DisplayItem[] {
  const grouped: DisplayItem[] = [];
  for (const item of items) {
    if (item.type !== "event") { grouped.push(item); continue; }
    const last = grouped[grouped.length - 1], questId = item.value.quest_id || null;
    if (last?.type === "group" && last.questId === questId) last.events.push(item.value);
    else grouped.push({ type: "group", questId, events: [item.value] });
  }
  return grouped;
}

export default function ChatTimeline({ messages, events, outgoing, quests, workerRuns, approvals, native,
  connected, historyMore, historyBusy, timelineError, conversationError, approvalError,
  canRetry, scrollRef, onScroll, onInspect, onLoadOlder, onRetry, onQuest, onApproval, approvalsBlocked, onApprovalDecision }: {
  messages: ChatMessage[]; events: TimelineEvent[]; outgoing: Outgoing[]; quests: Quest[]; workerRuns: WorkerRun[]; approvals: Row[];
  native: boolean; connected: boolean; historyMore: boolean; historyBusy: boolean; timelineError: string;
  conversationError: string; approvalError: string; canRetry: boolean; scrollRef: RefObject<HTMLDivElement>;
  onScroll: () => void; onInspect: () => void; onLoadOlder: () => void; onRetry: (item: Outgoing) => void;
  onQuest: (id: string) => void; onApproval: (id: string) => void;
  approvalsBlocked: boolean; onApprovalDecision: (item: Row, decision: "APPROVED" | "REJECTED") => void;
}) {
  const memory = useRef<EventViewMemory>({ expansion: new Map(), commandScroll: new Map() }).current;
  const items = groupEvents(mergeTimeline(messages, events, outgoing));
  const active = quests.filter((quest) => !isClosedQuest(quest.status)).sort((left, right) => Number(needsQuestAttention(right.status)) - Number(needsQuestAttention(left.status)));
  return <div className="timeline" ref={scrollRef} onScroll={onScroll} onMouseUp={() => { if (window.getSelection()?.toString()) onInspect(); }} aria-label="对话历史">
    {historyMore && <button className="text-button history" disabled={historyBusy} onClick={onLoadOlder}>{historyBusy ? "正在加载…" : "加载更早的消息与记录"}</button>}
    {conversationError && <p className="notice error" role="alert">{conversationError}</p>}
    {timelineError && <p className="notice error" role="alert">过程记录暂不可用：{timelineError}</p>}
    {!items.length && <div className="empty-conversation"><h2>有什么可以帮你？</h2><p>直接说目标，也可以继续之前的任务。</p></div>}
import { useLayoutEffect, useRef, useState, type ReactNode } from "react";

/** Keep native summary keyboard semantics, and retain the subtree through collapse. */
export default function AnimatedDetails({ className, summary, summaryLabel, summaryTitle, scrollKey, initialExpanded = false, onExpandedChange, children, onInspect }: {
  className: string; summary: ReactNode; summaryLabel?: string; summaryTitle?: string; scrollKey?: string;
  initialExpanded?: boolean; onExpandedChange?: (expanded: boolean) => void; children: ReactNode; onInspect: () => void;
}) {
  const [expanded, setExpanded] = useState(initialExpanded);
  const [present, setPresent] = useState(initialExpanded);
  const initial = useRef(initialExpanded);
  const animatedExpanded = useRef(initialExpanded);
  const desired = useRef(initialExpanded);
  const panel = useRef<HTMLDivElement>(null);

  // Depend only on user expansion. Polling must not restart animations or move scroll positions.
  useLayoutEffect(() => {
    const element = panel.current;
    if (!element) return;
    element.toggleAttribute("inert", !expanded);
    // A regrouped event restores its measured-open state without replaying an animation.
    if (animatedExpanded.current === expanded) return;
    animatedExpanded.current = expanded;
    const finish = () => {
      element.style.height = desired.current ? "auto" : "0px";
      element.style.opacity = desired.current ? "1" : "0";
      if (!desired.current) setPresent(false);
    };
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) { finish(); return; }
    const height = element.getBoundingClientRect().height;
    const opacity = getComputedStyle(element).opacity;
    element.style.height = `${height}px`;
    element.style.opacity = opacity;
    // Establish the current rendered height before transitioning to the measured target.
    void element.offsetHeight;
    let timeout = 0;
    const frame = requestAnimationFrame(() => {
      element.style.height = expanded ? `${element.scrollHeight}px` : "0px";
      element.style.opacity = expanded ? "1" : "0";
      const seconds = Number.parseFloat(getComputedStyle(element).getPropertyValue("--transition-duration-basic")) || .15;
      timeout = window.setTimeout(finish, seconds * 1000 + 50);
    });
    const transitioned = (event: TransitionEvent) => {
      if (event.target === element && event.propertyName === "height") finish();
    };
    element.addEventListener("transitionend", transitioned);
    return () => { cancelAnimationFrame(frame); window.clearTimeout(timeout); element.removeEventListener("transitionend", transitioned); };
  }, [expanded]);

  return <details className={className} data-scroll-key={scrollKey} open={present}>
    <summary aria-label={summaryLabel} aria-expanded={expanded} title={summaryTitle || undefined} onClick={(event) => {
      event.preventDefault();
      onInspect();
      desired.current = !desired.current;
      onExpandedChange?.(desired.current);
      setPresent(true);
      setExpanded(desired.current);
    }}>{summary}</summary>
    <div ref={panel} className="detail-collapsible" style={{ height: initial.current ? "auto" : "0px", opacity: initial.current ? 1 : 0 }}>{children}</div>
  </details>;
}

